"use strict";export function estimateWaitSeconds({queuepos,ownqueuepositions,requesttype,runnerstatus}){if(queuepos==null||runnerstatus==null||runnerstatus.stale){return null}const typicalruntime=runnerstatus.typical_runtime_seconds?.[requesttype];if(!(typicalruntime>0)){return null}const ownahead=ownqueuepositions.filter(position=>position<queuepos).length;const otherahead=queuepos-ownahead;const concurrency=Math.max(1,Math.min(runnerstatus.numslots||1,runnerstatus.distinct_queued_users||1));return Math.max(ownahead,otherahead/concurrency)*typicalruntime}export function formatWaitEstimate(seconds){if(seconds==null||!isFinite(seconds)){return null}if(seconds<60){return"under a minute"}if(seconds<90*60){return"~"+Math.ceil(seconds/60)+" min"}if(seconds>=4*60*60){return"over 4 hours"}return"~"+Math.ceil(seconds/3600)+" hours"}export function formatDuration(seconds){if(seconds==null||!isFinite(seconds)||seconds<0){return null}if(seconds<60){return Math.round(seconds)+"s"}if(seconds<3600){return Math.floor(seconds/60)+"m "+String(Math.round(seconds%60)).padStart(2,"0")+"s"}return Math.floor(seconds/3600)+"h "+String(Math.floor(seconds%3600/60)).padStart(2,"0")+"m"}
